package com.nephh.business;
import com.nephh.common.ApiResponse;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.security.core.annotation.AuthenticationPrincipal;
import org.springframework.security.oauth2.jwt.Jwt;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import java.util.*;
import static com.nephh.business.AccessService.*;

@RestController @RequestMapping("/api/business")
public class NodeController {
 private final JdbcTemplate db;private final AccessService access;
 public NodeController(JdbcTemplate db,AccessService access){this.db=db;this.access=access;}
 @GetMapping("/corridors") public ApiResponse<?> corridors(@AuthenticationPrincipal Jwt jwt){var a=access.actor(jwt);return ApiResponse.ok(a.role().equals("ADMIN")?db.queryForList("select * from corridor order by id"):db.queryForList("select distinct c.* from corridor c join area ar on ar.corridor_id=c.id join user_area ua on ua.area_id=ar.id where ua.user_id=?",a.id()));}
 @PostMapping("/corridors") public ApiResponse<?> corridor(@AuthenticationPrincipal Jwt jwt,@RequestBody Map<String,Object>b){var a=access.actor(jwt);access.admin(a);String name=text(b,"name",100);long id=access.insert("insert into corridor(name,description) values(?,?)",name,Objects.toString(b.get("description"),""));access.audit(a,"CREATE","CORRIDOR",id,null,name);return ApiResponse.ok(Map.of("id",id));}
 @PutMapping("/corridors/{id}") public ApiResponse<?> updateCorridor(@AuthenticationPrincipal Jwt jwt,@PathVariable long id,@RequestBody Map<String,Object>b){var a=access.actor(jwt);access.admin(a);var before=access.one("select * from corridor where id=?",id);db.update("update corridor set name=?,description=? where id=?",text(b,"name",100),Objects.toString(b.get("description"),""),id);access.audit(a,"UPDATE","CORRIDOR",id,before,b);return ApiResponse.ok(null);}
 @DeleteMapping("/corridors/{id}") public ApiResponse<?> deleteCorridor(@AuthenticationPrincipal Jwt jwt,@PathVariable long id){var a=access.actor(jwt);access.admin(a);var before=access.one("select * from corridor where id=?",id);db.update("delete from corridor where id=?",id);access.audit(a,"DELETE","CORRIDOR",id,before,null);return ApiResponse.ok(null);}
 @GetMapping("/areas") public ApiResponse<?> areas(@AuthenticationPrincipal Jwt jwt){var a=access.actor(jwt);return ApiResponse.ok(a.role().equals("ADMIN")?db.queryForList("select * from area order by id"):db.queryForList("select a.* from area a join user_area u on u.area_id=a.id where u.user_id=? order by a.id",a.id()));}
 @PostMapping("/areas") public ApiResponse<?> area(@AuthenticationPrincipal Jwt jwt,@RequestBody Map<String,Object> b){var a=access.actor(jwt);access.admin(a);String name=text(b,"name",100);long corridor=b.get("corridorId")==null?1:number(b,"corridorId");access.one("select id from corridor where id=?",corridor);db.update("insert into area(name,description,corridor_id) values(?,?,?)",name,Objects.toString(b.get("description"),""),corridor);access.audit(a,"CREATE","AREA",name,null,b);return ApiResponse.ok(null);}
 @GetMapping("/sections") public ApiResponse<?> sections(@AuthenticationPrincipal Jwt jwt,@RequestParam long areaId){var a=access.actor(jwt);access.area(a,areaId);return ApiResponse.ok(db.queryForList("select * from section where area_id=?",areaId));}
 @PutMapping("/areas/{id}") public ApiResponse<?> updateArea(@AuthenticationPrincipal Jwt jwt,@PathVariable long id,@RequestBody Map<String,Object>b){var a=access.actor(jwt);access.admin(a);var before=access.one("select * from area where id=?",id);long corridor=b.get("corridorId")==null?((Number)before.get("corridor_id")).longValue():number(b,"corridorId");access.one("select id from corridor where id=?",corridor);db.update("update area set name=?,description=?,corridor_id=? where id=?",text(b,"name",100),Objects.toString(b.get("description"),""),corridor,id);access.audit(a,"UPDATE","AREA",id,before,b);return ApiResponse.ok(null);}
 @DeleteMapping("/areas/{id}") public ApiResponse<?> deleteArea(@AuthenticationPrincipal Jwt jwt,@PathVariable long id){var a=access.actor(jwt);access.admin(a);var before=access.one("select * from area where id=?",id);db.update("delete from area where id=?",id);access.audit(a,"DELETE","AREA",id,before,null);return ApiResponse.ok(null);}
 @PutMapping("/sections/{id}") public ApiResponse<?> updateSection(@AuthenticationPrincipal Jwt jwt,@PathVariable long id,@RequestBody Map<String,Object>b){var a=access.actor(jwt);access.manager(a);var before=access.one("select * from section where id=?",id);access.area(a,((Number)before.get("area_id")).longValue());db.update("update section set name=? where id=?",text(b,"name",100),id);access.audit(a,"UPDATE","SECTION",id,before,b);return ApiResponse.ok(null);}
 @DeleteMapping("/sections/{id}") public ApiResponse<?> deleteSection(@AuthenticationPrincipal Jwt jwt,@PathVariable long id){var a=access.actor(jwt);access.manager(a);var before=access.one("select * from section where id=?",id);access.area(a,((Number)before.get("area_id")).longValue());db.update("delete from section where id=?",id);access.audit(a,"DELETE","SECTION",id,before,null);return ApiResponse.ok(null);}
 @PostMapping("/sections") public ApiResponse<?> section(@AuthenticationPrincipal Jwt jwt,@RequestBody Map<String,Object> b){var a=access.actor(jwt);access.manager(a);long area=number(b,"areaId");access.area(a,area);long id=access.insert("insert into section(area_id,name) values(?,?)",area,text(b,"name",100));access.audit(a,"CREATE","SECTION",id,null,b);return ApiResponse.ok(null);}
 @GetMapping("/nodes") public ApiResponse<?> nodes(@AuthenticationPrincipal Jwt jwt){var a=access.actor(jwt);var list=a.role().equals("ADMIN")?db.queryForList("select n.*,a.name area_name from monitoring_node n join area a on n.area_id=a.id order by n.id"):db.queryForList("select n.*,a.name area_name from monitoring_node n join area a on n.area_id=a.id join user_area u on u.area_id=n.area_id where u.user_id=? order by n.id",a.id());for(var n:list){long id=((Number)n.get("id")).longValue();var latest=new ArrayList<Map<String,Object>>();for(String metric:TelemetryService.UNITS.keySet())latest.addAll(db.queryForList("select * from telemetry where node_id=? and metric=? order by collected_at desc,id desc limit 1",id,metric));n.put("latest",latest);n.put("active_alarms",db.queryForObject("select count(*) from alarm where node_id=? and recovered_at is null",Integer.class,id));}return ApiResponse.ok(list);}
 @PostMapping("/nodes") @Transactional public ApiResponse<?> create(@AuthenticationPrincipal Jwt jwt,@RequestBody Map<String,Object>b){var a=access.actor(jwt);access.manager(a);long area=number(b,"areaId");access.area(a,area);String code=text(b,"code",64),location=text(b,"location",200);db.update("insert into monitoring_node(code,area_id,location,external_id,platform) values(?,?,?,?,?)",code,area,location,Objects.toString(b.get("externalId"),""),Objects.toString(b.get("platform"),"SIMULATOR"));var id=db.queryForObject("select id from monitoring_node where code=?",Long.class,code);access.audit(a,"CREATE","NODE",id,null,b);return ApiResponse.ok(Map.of("id",id));}
 @PutMapping("/nodes/{id}") @Transactional public ApiResponse<?> update(@AuthenticationPrincipal Jwt jwt,@PathVariable long id,@RequestBody Map<String,Object>b){var a=access.actor(jwt);access.manager(a);var before=access.node(a,id);String location=text(b,"location",200);int seconds=(int)number(b,"reportSeconds");if(seconds<5||seconds>86400)bad("上报周期应为5至86400秒");double x=Double.parseDouble(Objects.toString(b.get("x"),"50")),y=Double.parseDouble(Objects.toString(b.get("y"),"50"));if(!Double.isFinite(x)||!Double.isFinite(y)||x<0||x>100||y<0||y>100)bad("坐标应在0至100之间");Long section=b.get("sectionId")==null?null:number(b,"sectionId");if(section!=null){var s=access.one("select area_id from section where id=?",section);if(((Number)s.get("area_id")).longValue()!=((Number)before.get("area_id")).longValue())bad("区段不属于节点区域");}Long owner=b.get("ownerId")==null?null:number(b,"ownerId");if(owner!=null){var user=access.one("select * from sys_user where id=? and enabled=true",owner);if(!user.get("role_code").equals("ADMIN")&&db.queryForObject("select count(*) from user_area where user_id=? and area_id=?",Integer.class,owner,before.get("area_id"))==0)bad("负责人未授权该区域");}
 String metrics=b.get("metrics")==null?before.get("metrics").toString():text(b,"metrics",200);for(String metric:metrics.split(","))if(!TelemetryService.UNITS.containsKey(metric))bad("监测指标不合法");db.update("update monitoring_node set owner_id=?,metrics=? where id=?",owner,metrics,id);
 db.update("update monitoring_node set location=?,enabled=?,maintenance=?,report_seconds=?,external_id=?,platform=?,x_position=?,y_position=?,section_id=? where id=?",location,Boolean.TRUE.equals(b.get("enabled")),Boolean.TRUE.equals(b.get("maintenance")),seconds,Objects.toString(b.get("externalId"),""),Objects.toString(b.get("platform"),"SIMULATOR"),x,y,section,id);access.audit(a,"UPDATE","NODE",id,before,b);return ApiResponse.ok(null);}
 @DeleteMapping("/nodes/{id}") public ApiResponse<?> delete(@AuthenticationPrincipal Jwt jwt,@PathVariable long id){var a=access.actor(jwt);access.manager(a);var n=access.node(a,id);db.update("delete from monitoring_node where id=?",id);access.audit(a,"DELETE","NODE",id,n,null);return ApiResponse.ok(null);}
}
